/** Sample the baked timeline at time t (linear interp). */
export function sample(t: number): number[] {
  const n = FRAMES.length;
  let tt = t % LOOP_T; if (tt < 0) tt += LOOP_T;
  const f = tt * 60;
  const i0 = Math.min(n - 2, Math.floor(f));
  const u = Math.min(1, Math.max(0, f - i0));
  const a = FRAMES[i0], b = FRAMES[i0 + 1], out = new Array(10);
  for (let k = 0; k < 10; k++) out[k] = a[k] + (b[k] - a[k]) * u;
  out[0] = tt;
  return out;
}
